+    static std::string hash_hex(const Horse::Deterministic::CanonicalHash& value)
+    {
+        constexpr char digits[] = "0123456789abcdef";
+        std::string text(value.size() * 2, '0');
+        for (std::size_t index = 0; index < value.size(); ++index)
+        {
+            const auto byte = std::to_integer<unsigned>(value[index]);
+            text[index * 2] = digits[byte >> 4];
+            text[index * 2 + 1] = digits[byte & 15];
+        }
+        return text;
+    }
+
+    void log_online_battle_visuals() noexcept
+    {
+        using namespace RC::Unreal;
+        const auto* characters = m_lux.battleCharaArray();
+        const auto count = characters ? characters->Num : -1;
+        Output::send<LogLevel::Default>(STR(
+            "[HorseMod] online qualification run_id={} battle_actor_count={} combat_round={}\n"),
+            RC::to_generic_string(m_online_run_id), count, m_online_combat_round.round());
+        if (!characters || !characters->Data || count < 0 || count > 8) return;
+        auto query_bool = [](Horse::Obj object, const wchar_t* name) -> int {
+            if (!object || !UObject::IsReal(object.raw())) return -1;
+            auto* function = object.raw()->GetFunctionByNameInChain(name);
+            if (!function || function->GetPropertiesSize() != sizeof(bool)) return -1;
+            bool result{};
+            object.raw()->ProcessEvent(function, &result);
+            return result ? 1 : 0;
+        };
+        auto** actors = static_cast<UObject**>(characters->Data);
+        for (int index = 0; index < count; ++index)
+        {
+            Horse::Obj actor{actors[index]};
+            if (!actor || !UObject::IsReal(actor.raw())) continue;
+            const auto mesh = actor.getObj(L"CharaMeshComponent");
+            const auto asset = mesh ? mesh.getObj(L"SkeletalMesh") : Horse::Obj{};
+            Output::send<LogLevel::Default>(STR(
+                "[HorseMod] online qualification run_id={} battle_actor slot={} player_index={} "
+                "chara_id={} weapon_id={} actor=0x{:x} mesh=0x{:x} asset={} "
+                "character_visible={} combined_visible={} model_erased={} mesh_visible={}\n"),
+                RC::to_generic_string(m_online_run_id), index,
+                actor.getValueOr<std::int32_t>(L"PlayerIndex", -1),
+                actor.getValueOr<std::int32_t>(L"CharaID", -1),
+                actor.getValueOr<std::int32_t>(L"WeaponID", -1),
+                reinterpret_cast<std::uintptr_t>(actor.raw()), reinterpret_cast<std::uintptr_t>(mesh.raw()),
+                asset ? asset.raw()->GetFullName() : STR("none"),
+                  query_bool(actor, L"GetCharacterVisibility"), query_bool(actor, L"GetCombinedCharacterVisibility"),
+                  query_bool(actor, L"GetModelErase"), query_bool(mesh, L"IsVisible"));
+            const auto* components = actor.getPtr<Horse::TArrHdr>(L"CreationComponents");
+            const auto component_count = components ? components->Num : -1;
+            std::int32_t pending_callbacks{-1};
+            // Native TickActor (1403D0590) drains the 0x50-byte callback array
+            // at +0x548. Read its count to distinguish pending setup from a
+            // fully built actor whose semantic visibility was suppressed.
+            Horse::SafeReadInt32(reinterpret_cast<const std::byte*>(actor.raw())
+                + 0x550, &pending_callbacks);
+            Output::send<LogLevel::Default>(STR(
+                "[HorseMod] online qualification run_id={} battle_actor_setup slot={} "
+                "setup_complete={} pending_callbacks={} creation_components={}\n"),
+                RC::to_generic_string(m_online_run_id), index,
+                query_bool(actor, L"IsSetupCompleted"), pending_callbacks, component_count);
+            if (!components || !components->Data || component_count < 0 || component_count > 64)
+                continue;
+            auto** meshes = static_cast<UObject**>(components->Data);
+            for (int part = 0; part < component_count; ++part)
+            {
+                Horse::Obj component{meshes[part]};
+                if (!component || !UObject::IsReal(component.raw())) continue;
+                const auto part_asset = component.getObj(L"SkeletalMesh");
+                Output::send<LogLevel::Default>(STR(
+                    "[HorseMod] online qualification run_id={} battle_actor_component "
+                    "slot={} part={} asset={} visible={}\n"),
+                    RC::to_generic_string(m_online_run_id), index, part,
+                    part_asset ? part_asset.raw()->GetFullName() : STR("none"),
+                    query_bool(component, L"IsVisible"));
+            }
+        }
+    }
+
+    bool online_combat_is_current() const noexcept
+    {
+        if (!m_online_combat_round.active()) return false;
+        const auto base = Horse::NativeBinding::imageBase();
+        std::int32_t mode{};
+        std::uint32_t round{};
+        std::uint16_t result{};
+        return Horse::SafeReadInt32(reinterpret_cast<const void*>(base + 0x4846364), &mode)
+            && Horse::SafeReadUInt32(reinterpret_cast<const void*>(base + 0x48463a4), &round)
+            && Horse::SafeReadUInt16(reinterpret_cast<const void*>(base + 0x4846408), &result)
+            && mode == 2 && result == 0 && round == m_online_combat_round.round();
+    }
