+// Engine-frame-boundary lease: a frontier never moves while acknowledgements
+// are pending. Failure does not release the lease; the lifecycle owner releases
+// it at EngineTickPost after choosing pre/post-ownership failure handling.
+class OnlinePrefixHandoff
+{
+public:
+    Status Begin(FrameCoordinate frontier, std::uint64_t context,
+        const CanonicalHash& hash, std::uint64_t now_ms) noexcept
+    {
+        if (active_ || frontier.generation == 0 || context == 0)
+            return Status::failure(FailureCode::IllegalTransition);
+        frontier_ = frontier;
+        context_ = context;
+        hash_ = hash;
+        started_ms_ = now_ms;
+        active_ = true;
+        return Status::success();
+    }
+    Status Verify(FrameCoordinate frontier, std::uint64_t context,
+        const CanonicalHash& hash, std::uint64_t now_ms) const noexcept
+    {
+        if (!active_) return Status::failure(FailureCode::IllegalTransition);
+        if (frontier != frontier_ || context != context_)
+            return Status::failure(FailureCode::IdentityMismatch);
+        if (hash != hash_) return Status::failure(FailureCode::StateHashMismatch);
+        if (now_ms < started_ms_ || now_ms - started_ms_ >= 10'000)
+            return Status::failure(FailureCode::Timeout);
+        return Status::success();
+    }
+    void Release() noexcept { *this = {}; }
+    [[nodiscard]] bool active() const noexcept { return active_; }
+    [[nodiscard]] FrameCoordinate frontier() const noexcept { return frontier_; }
+    [[nodiscard]] std::uint64_t elapsed_ms(std::uint64_t now) const noexcept
+    { return now >= started_ms_ ? now - started_ms_ : 0; }
+private:
+    bool active_{};
+    FrameCoordinate frontier_{};
+    std::uint64_t context_{};
+    CanonicalHash hash_{};
+    std::uint64_t started_ms_{};
+};
