+Status Sc6ReplayNativeBridge::RestorePlaybackSource(
+    const ReplaySourceState& expected_current,
+    const ReplaySourceState& target) const noexcept
+{
+    ReplaySourceState current{};
+    const Status captured = CapturePlaybackSource(current);
+    if (!captured.ok()) return captured;
+    if (current != expected_current || !current.SameRecording(target)
+        || target.cursor < 0)
+        return Status::failure(FailureCode::RestorePreflightFailed);
+    auto* cursor = reinterpret_cast<std::byte*>(current.owner) + 0x3a0;
+    const bool written = safe_copy(cursor, &target.cursor, sizeof(target.cursor));
+    ReplaySourceState verified{};
+    if (written && CapturePlaybackSource(verified).ok() && verified == target)
+        return Status::success();
+    if (!safe_copy(cursor, &current.cursor, sizeof(current.cursor))
+        || !CapturePlaybackSource(verified).ok() || verified != current)
+        return Status::failure(FailureCode::UndoFailed);
+    return Status::failure(FailureCode::RestoreVerificationFailed);
+}
