+void test_prefix_confirmation_drain_holds_a_fixed_native_frontier()
+{
+    OnlinePrefixHandoff handoff;
+    expect(handoff.Begin({1, 242}, 123, hash(1), 100).ok(),
+        "handoff retains its boundary across service calls");
+    for (std::uint64_t elapsed : {1, 20, 500, 9'999})
+        expect(handoff.Verify({1, 242}, 123, hash(1), 100 + elapsed).ok(),
+            "delayed acknowledgement does not move or renew the frontier");
+    expect(!handoff.Begin({1, 243}, 123, hash(1), 500).ok()
+        && !handoff.Verify({1, 243}, 123, hash(1), 500).ok()
+        && !handoff.Verify({1, 242}, 124, hash(1), 500).ok()
+        && !handoff.Verify({1, 242}, 123, hash(2), 500).ok(),
+        "handoff rejects cursor, identity and canonical drift");
+    expect(handoff.Verify({1, 242}, 123, hash(1), 10'100).code == FailureCode::Timeout
+        && handoff.active(), "timeout retains lease until lifecycle handles failure");
+    handoff.Release();
+    expect(handoff.Begin({2, 390}, 456, hash(2), 11'000).ok(),
+        "released handoff admits a new round identity");
+    handoff.Release();
+    expect(NeedsOnlinePrefixConfirmationDrain(
+            120, 118, {1, 243}, {1, 242}),
+        "a one-frame confirmation lag drains after catch-up reaches the boundary");
+    expect(!NeedsOnlinePrefixConfirmationDrain(
+            120, 119, {1, 243}, {1, 242}),
+        "a confirmed fixed frontier needs no drain");
+    expect(!NeedsOnlinePrefixConfirmationDrain(
+            119, 117, {1, 242}, {1, 242}),
+        "catch-up must reach the native boundary before confirmation draining");
+}
