+bool DecisionQuery(RC::Unreal::UObject* widget, const wchar_t* name,
+    const wchar_t* output, bool& decided, int side = -1) noexcept
+{
+    decided = false;
+    auto* function = IsReal(widget) ? widget->GetFunctionByNameInChain(name) : nullptr;
+    if (!function || function->GetPropertiesSize() <= 0 || function->GetPropertiesSize() > 512)
+        return false;
+    auto* result = RC::Unreal::CastField<RC::Unreal::FBoolProperty>(Param(function, output));
+    if (!result) return false;
+    std::vector<std::uint8_t> params(function->GetPropertiesSize(), 0);
+    if (side >= 0 && !WriteInteger(Param(function, L"InSide"), params.data(), side)) return false;
+    try {
+        widget->ProcessEvent(function, params.data());
+        decided = result->GetPropertyValueInContainer(params.data());
+        return true;
+    } catch (...) { return false; }
+}
