+std::string CharacterSyncObservation(RC::Unreal::UObject* scene) noexcept
+{
+    auto* widget = ObjectProperty(scene, L"RefCharaSelect");
+    auto* sync = ObjectProperty(scene, L"MatchSettingSync");
+    auto* state = CurrentSetupState(scene);
+    bool left{}, right{}, subscribed{};
+    const bool flags = DecisionQuery(widget, L"IsDecidedPlayer", L"bDecided", left, 0)
+        && DecisionQuery(widget, L"IsDecidedPlayer", L"bDecided", right, 1);
+    std::uint8_t profile{}, character{}, stage{}, substate{};
+    const bool received = IsReal(sync) && ReadBattleSyncFlags(sync, profile, character, stage, &substate);
+    if (IsReal(sync) && IsReal(state))
+    {
+        auto* property = RC::Unreal::CastField<RC::Unreal::FMulticastDelegateProperty>(
+            sync->GetPropertyByNameInChain(L"OnRecvBattleSync"));
+        if (property)
+        {
+            // UE4.17 stores the multicast invocation list inline. The
+            // GetMulticastDelegate virtual was added in UE4.23; UE4SS throws
+            // for that wrapper on this game. Inspect the reflected slot.
+            static_assert(sizeof(RC::Unreal::FMulticastScriptDelegate) == 0x10);
+            const auto* delegate = property->GetSize() == 0x10
+                ? property->ContainerPtrToValuePtr<RC::Unreal::FMulticastScriptDelegate>(sync) : nullptr;
+            subscribed = delegate && delegate->Num() >= 0 && delegate->Num() <= 64
+                && delegate->Contains(state, RC::Unreal::FName(L"OnRecvBattleSync", RC::Unreal::FNAME_Add));
+        }
+    }
+    return std::string("decided=") + (flags ? (left ? "1" : "0") : "?") + "/"
+        + (flags ? (right ? "1" : "0") : "?") + ":subscribed=" + (subscribed ? "1" : "0")
+        + ":received=" + (received ? std::to_string(character) : "?")
+        + ":substate=" + (received ? std::to_string(substate) : "?") + ":state=" + ClassName(state)
+        + ":codes=" + StringProperty(scene, L"DecidedCharaCode_L") + "/"
+        + StringProperty(scene, L"DecidedCharaCode_R")
+        + ":timer=" + std::to_string(SelectionTimer(widget));
+}
