+RC::Unreal::UObject* CurrentCharacterPreview(RC::Unreal::UObject* manager, std::uint8_t side) noexcept
+{
+    using namespace RC::Unreal;
+    auto* function = IsReal(manager) ? manager->GetFunctionByNameInChain(L"GetPreviewChara") : nullptr;
+    if (!function || function->GetPropertiesSize() <= 0 || function->GetPropertiesSize() > 128) return nullptr;
+    auto* tag = CastField<FNameProperty>(Param(function, L"InDemoHumanTag"));
+    auto* output = Param(function, L"PreviewChara");
+    if (!tag || !output || output->GetSize() != sizeof(UObject*)) return nullptr;
+    std::vector<std::uint8_t> params(function->GetPropertiesSize(), 0);
+    *tag->ContainerPtrToValuePtr<FName>(params.data()) = FName(side == 0 ? L"Left" : L"Right", FNAME_Add);
+    manager->ProcessEvent(function, params.data());
+    auto* actor = *output->ContainerPtrToValuePtr<UObject*>(params.data());
+    return IsReal(actor) ? actor : nullptr;
+}
+
+RC::Unreal::UObject* CurrentBattlePlayerSetup(RC::Unreal::UObject* scene, std::uint8_t side) noexcept
+{
+    using namespace RC::Unreal;
+    if (!IsReal(scene)) return nullptr;
+    auto* world = reinterpret_cast<UObject*>(scene->GetWorld());
+    auto* instance = ObjectProperty(world, L"OwningGameInstance");
+    auto* function = IsReal(instance) ? instance->GetFunctionByNameInChain(L"GetBattleSetup") : nullptr;
+    if (!function || function->GetPropertiesSize() != sizeof(UObject*)) return nullptr;
+    UObject* setup{};
+    instance->ProcessEvent(function, &setup);
+    return ObjectProperty(setup, side == 0 ? L"PlayerLeft" : L"PlayerRight");
+}
+
+int ByteField(RC::Unreal::UObject* object, const wchar_t* name) noexcept
+{
+    auto* property = IsReal(object) ? object->GetPropertyByNameInChain(name) : nullptr;
+    return property && property->GetSize() == 1
+        ? *property->ContainerPtrToValuePtr<std::uint8_t>(object) : -1;
+}
+
+int SelectionIntegerField(RC::Unreal::UObject* object, const wchar_t* name) noexcept
+{
+    auto* property = IsReal(object) ? object->GetPropertyByNameInChain(name) : nullptr;
+    if (property && property->GetSize() == sizeof(std::int32_t))
+        return *property->ContainerPtrToValuePtr<std::int32_t>(object);
+    return ByteField(object, name);
+}
