+bool CharacterPreviewReady(RC::Unreal::UObject* scene, std::uint8_t side,
+    std::string_view code, const CharacterSelectionProgress& progress, std::string& detail) noexcept
+{
+    using namespace RC::Unreal;
+    auto* manager = ObjectProperty(scene, L"RefPreviewManager");
+    auto* actor = CurrentCharacterPreview(manager, side);
+    auto* profile = ObjectProperty(actor, L"PreviewProfile");
+    auto* preview_setup = ObjectProperty(actor, L"PreviewPlayerSetup");
+    auto* battle_setup = CurrentBattlePlayerSetup(scene, side);
+    auto* battle_profile = ObjectProperty(battle_setup, L"CreationProfile");
+    auto* ready = IsReal(actor) ? CastField<FBoolProperty>(actor->GetPropertyByNameInChain(L"bReadyDemoHuman")) : nullptr;
+    const bool loaded = ready && ready->GetPropertyValueInContainer(actor);
+    const auto style = ByteField(profile, L"Style");
+    const auto weapon = ByteField(profile, L"WeaponVariation");
+    const bool identity = IsReal(profile) && profile == battle_profile
+        // Native CreateBattlePlayerSetupFromProfile (140418E40) stores
+        // the passed profile directly; it does not duplicate it.
+        && profile == ObjectProperty(preview_setup, L"CreationProfile")
+        && StringProperty(manager, side == 0 ? L"CharaCode_L" : L"CharaCode_R") == code
+        && style >= 0 && style != 255
+        && style == ByteField(manager, side == 0 ? L"FightStyle_L" : L"FightStyle_R")
+        && weapon >= 0 && weapon == ByteField(manager, side == 0 ? L"WeaponVariation_L" : L"WeaponVariation_R")
+        && (!progress.require_replacement || reinterpret_cast<std::uintptr_t>(actor) != progress.prior_preview);
+    detail = "preview_ready=" + std::to_string(loaded) + ":profile_matches=" + std::to_string(identity)
+        + ":style=" + std::to_string(style) + ":weapon=" + std::to_string(weapon)
+        + ":preview=" + std::to_string(reinterpret_cast<std::uintptr_t>(actor))
+        + ":preview_setup_profile=" + std::to_string(reinterpret_cast<std::uintptr_t>(ObjectProperty(preview_setup, L"CreationProfile")))
+        + ":battle_profile=" + std::to_string(reinterpret_cast<std::uintptr_t>(battle_profile));
+    return loaded && identity;
+}
