+bool ConfirmStage(RC::Unreal::UObject* scene, RC::Unreal::UObject* widget,
+    std::string_view expected_code) noexcept
+{
+    // StageSelect.HandleInput bytecode: InputType=1, Key=16 runs the full
+    // DecideStage + bDecidedLeftPlayer + DecideCursor path. A direct
+    // RequestInputCommand omits the latter two and can wait for timer expiry.
+    auto* getter = IsReal(widget) ? widget->GetFunctionByNameInChain(L"GetActiveInputIndex") : nullptr;
+    auto* handle = IsReal(widget) ? widget->GetFunctionByNameInChain(L"HandleInput") : nullptr;
+    if (!getter || !handle || getter->GetPropertiesSize() <= 0 || getter->GetPropertiesSize() > 512
+        || handle->GetPropertiesSize() <= 0 || handle->GetPropertiesSize() > 512) return false;
+    auto* index = RC::Unreal::CastField<RC::Unreal::FIntProperty>(Param(getter, L"Index"));
+    auto* prevented = RC::Unreal::CastField<RC::Unreal::FBoolProperty>(Param(handle, L"IsDefaultPrevented"));
+    if (!index || !prevented) return false;
+    std::vector<std::uint8_t> query(getter->GetPropertiesSize(), 0);
+    std::vector<std::uint8_t> params(handle->GetPropertiesSize(), 0);
+    try {
+        widget->ProcessEvent(getter, query.data());
+        const auto controller = *index->ContainerPtrToValuePtr<std::int32_t>(query.data());
+        if (controller < 0 || !WriteInteger(Param(handle, L"ControllerId"), params.data(), controller)
+            || !WriteInteger(Param(handle, L"InputType"), params.data(), 1)
+            || !WriteInteger(Param(handle, L"Key"), params.data(), 16)) return false;
+        prevented->SetPropertyValueInContainer(params.data(), false);
+        widget->ProcessEvent(handle, params.data());
+    } catch (...) { return false; }
+    bool decided{};
+    return DecisionQuery(widget, L"IsDecided", L"bDecide", decided) && decided
+        && StringProperty(scene, L"DecidedStageCode") == expected_code;
 }

